{'role': 'user', 'content': [{'tool_use_id': 'toolu_01QwoRYfJF8ikEN5653GxNTG', 'type': 'tool_result', 'content': '     1→import { create } from "zustand";
     2→import type { BridgeStatus, DeviceInfo, PlayerInfo, BridgeState } from "../types";
     3→
     4→export type DotStatus = "connected" | "disconnected" | "degraded";
     5→
     6→interface BridgeStoreState {
     7→  // WebSocket connection state
     8→  wsConnected: boolean;
     9→
    10→  // Bridge state (from WebSocket bridge_status messages)
    11→  status: BridgeStatus;
    12→  port: number;
    13→  networkInterface: string | null;
    14→  jarExists: boolean;
    15→  jreAvailable: boolean;
    16→  restartCount: number;
    17→  restartAttempt: number;
    18→  nextRetryInS: number | null;
    19→  routeCorrect: boolean | null;
    20→  routeWarning: string | null;
    21→  devices: Record<string, DeviceInfo>;
    22→  players: Record<string, PlayerInfo>;
    23→
    24→  // Pioneer liveness (from WebSocket pioneer_status messages)
    25→  isReceiving: boolean;
    26→  lastMessageAgeMs: number;
    27→  bridgeConnected: boolean;
    28→
    29→  // Computed status for TopBar StatusDot
    30→  dotStatus: DotStatus;
    31→
    32→  // True while WS is not yet connected OR bridge is still launching.
    33→  // Clears once the WS has connected and the bridge reaches a stable state.
    34→  isStartingUp: boolean;
    35→
    36→  // Actions
    37→  setWsConnected: (connected: boolean) => void;
    38→  setBridgeState: (state: BridgeState) => void;
    39→  setPioneerStatus: (isReceiving: boolean, ageMs: number, bridgeConnected: boolean) => void;
    40→}
    41→
    42→function computeDotStatus(status: BridgeStatus): DotStatus {
    43→  if (status === "running") return "connected";
    44→  if (status === "fallback" || status === "waiting_for_hardware") return "degraded";
    45→  return "disconnected";
    46→}
    47→
    48→/** Startup is in progress until WS is open AND bridge has left "starting". */
    49→function computeIsStartingUp(wsConnected: boolean, status: BridgeStatus): boolean {
    50→  return !wsConnected || status === "starting";
    51→}
    52→
    53→export const useBridgeStore = create<BridgeStoreState>((set) => ({
    54→  wsConnected: false,
    55→  status: "stopped",
    56→  port: 0,
    57→  networkInterface: null,
    58→  jarExists: false,
    59→  jreAvailable: false,
    60→  restartCount: 0,
    61→  restartAttempt: 0,
    62→  nextRetryInS: null,
    63→  routeCorrect: null,
    64→  routeWarning: null,
    65→  devices: {},
    66→  players: {},
    67→  isReceiving: false,
    68→  lastMessageAgeMs: -1,
    69→  bridgeConnected: false,
    70→  dotStatus: "disconnected",
    71→  isStartingUp: true,
    72→
    73→  setWsConnected: (connected: boolean) =>
    74→    set((prev) => ({
    75→      wsConnected: connected,
    76→      isStartingUp: computeIsStartingUp(connected, prev.status),
    77→      // Clear stale device/player data on WS disconnect so components
    78→      // show empty state instead of last-known values.
    79→      ...(connected ? {} : { devices: {}, players: {} }),
    80→    })),
    81→
    82→  setBridgeState: (state: BridgeState) =>
    83→    set((prev) => {
    84→      const isRunning = state.status === "running";
    85→      return {
    86→        status: state.status,
    87→        port: state.port,
    88→        networkInterface: state.network_interface,
    89→        jarExists: state.jar_exists,
    90→        jreAvailable: state.jre_available,
    91→        restartCount: state.restart_count,
    92→        restartAttempt: state.restart_attempt,
    93→        nextRetryInS: state.next_retry_in_s,
    94→        routeCorrect: state.route_correct,
    95→        routeWarning: state.route_warning,
    96→        // Trust device/player data only when bridge is running.
    97→        // In non-running states the backend adapter may retain stale
    98→        // entries, so force-clear on the frontend side.
    99→        devices: isRunning ? state.devices : {},
   100→        players: isRunning ? state.players : {},
   101→        dotStatus: computeDotStatus(state.status),
   102→        isStartingUp: computeIsStartingUp(prev.wsConnected, state.status),
   103→      };
   104→    }),
   105→
   106→  setPioneerStatus: (isReceiving: boolean, ageMs: number, bridgeConnected: boolean) =>
   107→    set((prev) => ({
   108→      isReceiving,
   109→      lastMessageAgeMs: ageMs,
   110→      bridgeConnected,
   111→      dotStatus: computeDotStatus(prev.status),
   112→    })),
   113→}));
   114→'}]}

{'role': 'user', 'content': [{'tool_use_id': 'toolu_01UawCNiUKNk3xPUZhTdfc4K', 'type': 'tool_result', 'content': '     1→/** WebSocket client — auto-reconnect, dispatches to Zustand stores.
     2→ *
     3→ * Per frontend/CLAUDE.md: Components never touch WS directly.
     4→ * This module manages the connection and routes typed messages to stores.
     5→ */
     6→
     7→import type { WSMessage } from "../types";
     8→import { useBridgeStore } from "../stores/bridgeStore";
     9→import { useConsoleStore } from "../stores/consoleStore";
    10→import { mapWSMessageToEntries } from "../utils/consoleMapper";
    11→
    12→const WS_URL = `ws://${window.location.hostname}:8000/ws`;
    13→
    14→let ws: WebSocket | null = null;
    15→let reconnectTimer: ReturnType<typeof setTimeout> | null = null;
    16→let backoff = 1000; // ms, doubles on each failure up to 30s
    17→const MAX_BACKOFF = 30000;
    18→
    19→function dispatchToConsole(msg: WSMessage): void {
    20→  const entries = mapWSMessageToEntries(msg);
    21→  const { addEntry } = useConsoleStore.getState();
    22→  for (const entry of entries) {
    23→    addEntry(entry);
    24→  }
    25→}
    26→
    27→function dispatch(msg: WSMessage): void {
    28→  switch (msg.type) {
    29→    case "bridge_status":
    30→      useBridgeStore.getState().setBridgeState(msg.payload);
    31→      break;
    32→    case "pioneer_status":
    33→      useBridgeStore
    34→        .getState()
    35→        .setPioneerStatus(
    36→          msg.payload.is_receiving,
    37→          msg.payload.last_message_age_ms,
    38→          msg.payload.bridge_connected,
    39→        );
    40→      break;
    41→  }
    42→  dispatchToConsole(msg);
    43→}
    44→
    45→function onOpen(): void {
    46→  backoff = 1000;
    47→  useBridgeStore.getState().setWsConnected(true);
    48→  useConsoleStore.getState().addEntry({
    49→    source: "system",
    50→    severity: "info",
    51→    message: "Connected to backend",
    52→    verbose: false,
    53→  });
    54→}
    55→
    56→function onMessage(event: MessageEvent): void {
    57→  try {
    58→    const msg = JSON.parse(event.data) as WSMessage;
    59→    dispatch(msg);
    60→  } catch {
    61→    // Ignore malformed messages
    62→  }
    63→}
    64→
    65→function onClose(): void {
    66→  ws = null;
    67→  useBridgeStore.getState().setWsConnected(false);
    68→  useConsoleStore.getState().addEntry({
    69→    source: "system",
    70→    severity: "error",
    71→    message: "Backend connection lost",
    72→    verbose: false,
    73→  });
    74→  scheduleReconnect();
    75→}
    76→
    77→function onError(): void {
    78→  ws?.close();
    79→}
    80→
    81→function scheduleReconnect(): void {
    82→  if (reconnectTimer) return;
    83→  reconnectTimer = setTimeout(() => {
    84→    reconnectTimer = null;
    85→    connectWebSocket();
    86→  }, backoff);
    87→  backoff = Math.min(backoff * 2, MAX_BACKOFF);
    88→}
    89→
    90→export function connectWebSocket(): void {
    91→  if (ws) return;
    92→
    93→  try {
    94→    ws = new WebSocket(WS_URL);
    95→    ws.onopen = onOpen;
    96→    ws.onmessage = onMessage;
    97→    ws.onclose = onClose;
    98→    ws.onerror = onError;
    99→  } catch {
   100→    scheduleReconnect();
   101→  }
   102→}
   103→
   104→export function disconnectWebSocket(): void {
   105→  if (reconnectTimer) {
   106→    clearTimeout(reconnectTimer);
   107→    reconnectTimer = null;
   108→  }
   109→  if (ws) {
   110→    ws.onclose = null; // Prevent reconnect
   111→    ws.close();
   112→    ws = null;
   113→  }
   114→}
   115→'}]}

{'role': 'user', 'content': [{'tool_use_id': 'toolu_01RZ5KJjRY5cpdb8A5akuqpz', 'type': 'tool_result', 'content': '     1→/** Console store — ring-buffered log entries with recording support.
     2→ *
     3→ * Independent store: does NOT import any other store.
     4→ */
     5→
     6→import { create } from "zustand";
     7→import type { ConsoleEntry, ConsoleSource, ConsoleSeverity } from "../types/console";
     8→
     9→const MAX_ENTRIES = 200;
    10→
    11→let nextId = 1;
    12→
    13→interface ConsoleStoreState {
    14→  entries: ConsoleEntry[];
    15→  verboseMode: boolean;
    16→  isRecording: boolean;
    17→  recordBuffer: ConsoleEntry[];
    18→
    19→  addEntry: (entry: Omit<ConsoleEntry, "id" | "timestamp">) => void;
    20→  setVerboseMode: (verbose: boolean) => void;
    21→  startRecording: () => void;
    22→  stopRecording: () => ConsoleEntry[];
    23→  clearEntries: () => void;
    24→}
    25→
    26→export type { ConsoleSource, ConsoleSeverity };
    27→
    28→export const useConsoleStore = create<ConsoleStoreState>((set, get) => ({
    29→  entries: [],
    30→  verboseMode: false,
    31→  isRecording: false,
    32→  recordBuffer: [],
    33→
    34→  addEntry: (partial) => {
    35→    const entry: ConsoleEntry = {
    36→      ...partial,
    37→      id: String(nextId++),
    38→      timestamp: Date.now(),
    39→    };
    40→
    41→    set((state) => {
    42→      const updated = [...state.entries, entry];
    43→      if (updated.length > MAX_ENTRIES) {
    44→        updated.splice(0, updated.length - MAX_ENTRIES);
    45→      }
    46→
    47→      const newState: Partial<ConsoleStoreState> = { entries: updated };
    48→
    49→      if (state.isRecording) {
    50→        newState.recordBuffer = [...state.recordBuffer, entry];
    51→      }
    52→
    53→      return newState;
    54→    });
    55→  },
    56→
    57→  setVerboseMode: (verbose) => set({ verboseMode: verbose }),
    58→
    59→  startRecording: () => set({ isRecording: true, recordBuffer: [] }),
    60→
    61→  stopRecording: () => {
    62→    const buffer = get().recordBuffer;
    63→    set({ isRecording: false, recordBuffer: [] });
    64→    return buffer;
    65→  },
    66→
    67→  clearEntries: () => set({ entries: [] }),
    68→}));
    69→'}]}

{'role': 'user', 'content': [{'tool_use_id': 'toolu_01UU3qHaV8CNX8zNrQHGqpUu', 'type': 'tool_result', 'content': '     1→/** Network API functions and TanStack Query hooks for interface/route management. */
     2→
     3→import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
     4→import { apiFetch } from "./client";
     5→import type {
     6→  InterfaceListResponse,
     7→  RouteStatusResponse,
     8→  RouteFixResponse,
     9→  RouteSetupStatus,
    10→  BridgeState,
    11→} from "../types";
    12→
    13→// --- Query hooks ---
    14→
    15→export function useInterfaces({ enabled = true }: { enabled?: boolean } = {}) {
    16→  return useQuery<InterfaceListResponse>({
    17→    queryKey: ["network", "interfaces"],
    18→    queryFn: () => apiFetch<InterfaceListResponse>("/network/interfaces"),
    19→    enabled,
    20→    refetchOnWindowFocus: true,
    21→    staleTime: 10_000,
    22→  });
    23→}
    24→
    25→export function useRouteStatus({ enabled = true }: { enabled?: boolean } = {}) {
    26→  return useQuery<RouteStatusResponse>({
    27→    queryKey: ["network", "route"],
    28→    queryFn: () => apiFetch<RouteStatusResponse>("/network/route"),
    29→    enabled,
    30→    refetchOnWindowFocus: true,
    31→    staleTime: 5_000,
    32→  });
    33→}
    34→
    35→export function useRouteSetupStatus({ enabled = true }: { enabled?: boolean } = {}) {
    36→  return useQuery<RouteSetupStatus>({
    37→    queryKey: ["network", "route", "setup-status"],
    38→    queryFn: () => apiFetch<RouteSetupStatus>("/network/route/setup-status"),
    39→    enabled,
    40→    staleTime: 60_000,
    41→  });
    42→}
    43→
    44→// --- Mutation functions ---
    45→
    46→export async function fixRoute(iface: string): Promise<RouteFixResponse> {
    47→  return apiFetch<RouteFixResponse>("/network/route/fix", {
    48→    method: "POST",
    49→    body: JSON.stringify({ interface: iface }),
    50→  });
    51→}
    52→
    53→export async function updateBridgeInterface(iface: string): Promise<unknown> {
    54→  return apiFetch("/bridge/settings", {
    55→    method: "PUT",
    56→    body: JSON.stringify({ network_interface: iface }),
    57→  });
    58→}
    59→
    60→export async function restartBridge(): Promise<BridgeState> {
    61→  return apiFetch<BridgeState>("/bridge/restart", {
    62→    method: "POST",
    63→  });
    64→}
    65→
    66→// --- Mutation hooks ---
    67→
    68→export function useFixRoute() {
    69→  const queryClient = useQueryClient();
    70→  return useMutation({
    71→    mutationFn: fixRoute,
    72→    onSuccess: () => {
    73→      queryClient.invalidateQueries({ queryKey: ["network", "route"] });
    74→    },
    75→  });
    76→}
    77→
    78→export function useRestartBridge() {
    79→  const queryClient = useQueryClient();
    80→  return useMutation({
    81→    mutationFn: restartBridge,
    82→    onSuccess: () => {
    83→      queryClient.invalidateQueries({ queryKey: ["network", "route"] });
    84→    },
    85→  });
    86→}
    87→'}]}

{'role': 'user', 'content': [{'tool_use_id': 'toolu_014VnZRKDW5rCVySHc9pZ7hp', 'type': 'tool_result', 'content': '     1→/** Maps incoming WS messages to ConsoleEntry objects for the console panel.
     2→ *
     3→ * Tracks previous state at module level for diff detection (Clean mode).
     4→ * Safe because there is exactly one WS connection (singleton).
     5→ */
     6→
     7→import type { WSMessage } from "../types/ws";
     8→import type { ConsoleEntry, ConsoleSource, ConsoleSeverity } from "../types/console";
     9→import type { BridgeStatus } from "../types/bridge";
    10→
    11→// ---------- Previous-state tracking for diff detection ----------
    12→
    13→let prevBridgeStatus: BridgeStatus | null = null;
    14→let prevIsReceiving: boolean | null = null;
    15→let prevBridgeConnected: boolean | null = null;
    16→let prevDeviceKeys: string[] = [];
    17→let prevRestartCount: number = 0;
    18→let prevRouteWarning: string | null = null;
    19→let prevJarExists: boolean | null = null;
    20→let prevJreAvailable: boolean | null = null;
    21→
    22→/** Reset all tracked state. Exposed for test isolation. */
    23→export function resetMapperState(): void {
    24→  prevBridgeStatus = null;
    25→  prevIsReceiving = null;
    26→  prevBridgeConnected = null;
    27→  prevDeviceKeys = [];
    28→  prevRestartCount = 0;
    29→  prevRouteWarning = null;
    30→  prevJarExists = null;
    31→  prevJreAvailable = null;
    32→}
    33→
    34→// ---------- Helpers ----------
    35→
    36→type PartialEntry = Omit<ConsoleEntry, "id" | "timestamp">;
    37→
    38→function clean(
    39→  source: ConsoleSource,
    40→  severity: ConsoleSeverity,
    41→  message: string,
    42→  raw?: unknown,
    43→): PartialEntry {
    44→  return { source, severity, message, verbose: false, raw };
    45→}
    46→
    47→function verbose(
    48→  source: ConsoleSource,
    49→  severity: ConsoleSeverity,
    50→  message: string,
    51→  raw?: unknown,
    52→): PartialEntry {
    53→  return { source, severity, message, verbose: true, raw };
    54→}
    55→
    56→function severityForStatus(status: BridgeStatus): ConsoleSeverity {
    57→  if (status === "crashed" || status === "no_jre" || status === "no_jar") return "error";
    58→  if (status === "fallback" || status === "waiting_for_hardware") return "warn";
    59→  return "info";
    60→}
    61→
    62→// ---------- Bridge status mapping ----------
    63→
    64→function mapBridgeStatus(payload: WSMessage & { type: "bridge_status" }): PartialEntry[] {
    65→  const s = payload.payload;
    66→  const entries: PartialEntry[] = [];
    67→
    68→  // --- Clean entries (diff detection) ---
    69→
    70→  // Status change
    71→  if (prevBridgeStatus !== null && s.status !== prevBridgeStatus) {
    72→    const sev = severityForStatus(s.status);
    73→    let msg = `Bridge ${prevBridgeStatus} \u2192 ${s.status}`;
    74→    if (s.status === "running" && s.network_interface) {
    75→      msg = `Bridge connected on ${s.network_interface} (port ${s.port})`;
    76→    } else if (s.status === "crashed") {
    77→      const retryPart = s.next_retry_in_s !== null ? `, retry in ${s.next_retry_in_s}s` : "";
    78→      msg = `Bridge crashed (restart ${s.restart_count}/3${retryPart})`;
    79→    } else if (s.status === "waiting_for_hardware") {
    80→      msg = "Bridge waiting for hardware (polling every 30s)";
    81→    } else if (s.status === "fallback") {
    82→      msg = "Bridge entered fallback mode";
    83→    }
    84→    entries.push(clean("bridge", sev, msg));
    85→  } else if (prevBridgeStatus === null && s.status !== "stopped") {
    86→    // First message with non-default status
    87→    entries.push(clean("bridge", severityForStatus(s.status), `Bridge status: ${s.status}`));
    88→  }
    89→
    90→  // Device discovery changes
    91→  const currentDeviceKeys = Object.keys(s.devices).sort();
    92→  if (prevBridgeStatus !== null) {
    93→    const added = currentDeviceKeys.filter((k) => !prevDeviceKeys.includes(k));
    94→    const removed = prevDeviceKeys.filter((k) => !currentDeviceKeys.includes(k));
    95→    for (const k of added) {
    96→      const d = s.devices[k];
    97→      entries.push(clean("bridge", "info", `Device discovered: ${d.device_name} (#${d.device_number})`));
    98→    }
    99→    for (const k of removed) {
   100→      entries.push(clean("bridge", "warn", `Device lost: ${k}`));
   101→    }
   102→  }
   103→
   104→  // Restart count increase
   105→  if (prevRestartCount !== null && s.restart_count > prevRestartCount) {
   106→    entries.push(clean("bridge", "warn", `Bridge restarted (count: ${s.restart_count})`));
   107→  }
   108→
   109→  // Route warning change
   110→  if (s.route_warning !== prevRouteWarning && s.route_warning !== null) {
   111→    entries.push(
